(()=>{
 const root=document.querySelector('#wcd');if(!root)return;
 const header=root.querySelector('header'),menu=root.querySelector('.menu'),nav=root.querySelector('#navigation'),shop=root.querySelector('.nav-shop'),shopToggle=root.querySelector('.shop-toggle');
 const updateHeader=()=>header.classList.toggle('is-scrolled',scrollY>24);updateHeader();addEventListener('scroll',updateHeader,{passive:true});
 const closeShop=()=>{shop.classList.remove('open');shopToggle.setAttribute('aria-expanded','false')};
 menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);if(!open)closeShop()});
 shopToggle.addEventListener('click',()=>{const open=shopToggle.getAttribute('aria-expanded')!=='true';shopToggle.setAttribute('aria-expanded',String(open));shop.classList.toggle('open',open)});
 nav.addEventListener('click',event=>{if(event.target.closest('a')){closeShop();menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}});
 document.addEventListener('click',event=>{if(!shop.contains(event.target))closeShop()});
 root.addEventListener('keydown',event=>{if(event.key!=='Escape')return;if(shop.classList.contains('open')){closeShop();shopToggle.focus()}else if(nav.classList.contains('open')){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');menu.focus()}});
 const holder=document.querySelector('#browse-content'),data=window.WCD_CATALOG,params=new URLSearchParams(location.search);
 const asset=name=>`assets/${name}`;
 const card=product=>`<a class="product-card" href="catalog.html?product=${product.id}"><img src="${asset(product.images[0])}" alt="${product.name}, first view" loading="lazy"><span class="product-card-copy"><span class="eyebrow">${data.categories.find(c=>c.id===product.category).name}</span><strong>${product.name}</strong><span class="text-link">View product</span></span></a>`;
 const categories=()=>`<nav class="category-nav" aria-label="Product categories"><a href="catalog.html">All categories</a>${data.categories.map(c=>`<a href="catalog.html?category=${c.id}">${c.name}</a>`).join('')}</nav>`;
 const category=params.get('category'),productId=params.get('product'),product=data.products.find(p=>p.id===productId),cat=data.categories.find(c=>c.id===category);
 if(product){
  const parent=data.categories.find(c=>c.id===product.category);document.title=`${product.name} — Wood Carving Decor`;
  holder.innerHTML=`<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="index.html">Home</a><span>/</span><a href="catalog.html">Collection</a><span>/</span><a href="catalog.html?category=${parent.id}">${parent.name}</a></nav><div class="product-detail"><div class="product-gallery"><img class="product-main-image" src="${asset(product.images[0])}" alt="${product.name}, view 1"><div class="product-thumbs" role="group" aria-label="Product views">${product.images.map((img,i)=>`<button type="button" data-image="${img}" data-index="${i+1}" aria-label="Show ${product.name}, view ${i+1}" aria-pressed="${i===0}"><img src="${asset(img)}" alt=""></button>`).join('')}</div></div><div class="product-description"><p class="eyebrow">${parent.title}</p><h1>${product.name}</h1><p>Representative product preview. Product specifications, availability, and pricing will be confirmed in the WooCommerce store.</p><a class="button" href="catalog.html?category=${parent.id}">Browse ${parent.name}</a><p><a class="text-link" href="index.html#questions">What to check before ordering</a></p></div></div><section class="related-products"><h2>More in ${parent.name}</h2><div class="product-grid">${data.products.filter(p=>p.category===product.category&&p.id!==product.id).map(card).join('')}</div></section>`;
  const main=holder.querySelector('.product-main-image');holder.querySelectorAll('[data-image]').forEach(button=>button.addEventListener('click',()=>{main.src=asset(button.dataset.image);main.alt=`${product.name}, view ${button.dataset.index}`;holder.querySelectorAll('[data-image]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)))}));
 }else if(cat){
  document.title=`${cat.name} — Wood Carving Decor`;
  holder.innerHTML=`<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="index.html">Home</a><span>/</span><a href="catalog.html">Collection</a></nav><p class="eyebrow">The Collection</p><h1>${cat.title}</h1><p class="browse-intro">${cat.description}</p>${categories()}<div class="product-grid">${data.products.filter(p=>p.category===cat.id).map(card).join('')}</div><p class="prototype-note">Representative products only. Product details and ordering will be finalized for WooCommerce.</p>`;
 }else{
  holder.innerHTML=`<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="index.html">Home</a><span>/</span>Collection</nav><p class="eyebrow">The Collection</p><h1>Details that Elevate Your Space</h1><p class="browse-intro">Explore decorative wood carvings in a variety of styles and sizes. From subtle embellishments to striking architectural accents, discover the pieces that make your project uniquely yours.</p>${categories()}<div class="browse-categories">${data.categories.map(c=>`<a href="catalog.html?category=${c.id}"><img src="${c.image}" alt="${c.title}" loading="lazy"><span><strong>${c.title}</strong><small>${c.description}</small><span class="text-link">${c.cta}</span></span></a>`).join('')}</div>`;
 }
})();
